'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\n\n', [[''], ['']]],
  ['a\n', [['a']]],
  ['a\r\nb\rc\n', [['a'], ['b'], ['c']]],
  ['\uFEFFa,b', [['a', 'b']]],
  ['a,\uFEFF', [['a', '\uFEFF']]],
  ['a"b,"c""d"', [['a"b', 'c"d']]],
  ['"x\r\ny\rz\n",q\r\n', [['x\r\ny\rz\n', 'q']]],
  ['"",""\n', [['', '']]],
  ['a,,\n', [['a', '', '']]],
  ['"a"\r', [['a']]],
  ['😀,b', [['😀', 'b']]],
];
for (const [input, expected] of cases) {
  assert.deepEqual(parse(input), expected, JSON.stringify(input));
  for (let i = 0; i <= input.length; i++) {
    for (let j = i; j <= input.length; j++) {
      const p = createParser();
      const out = [];
      for (const part of [input.slice(0, i), '', input.slice(i, j), input.slice(j)]) out.push(...p.push(part));
      out.push(...p.end());
      assert.deepEqual(out, expected, `${JSON.stringify(input)} @${i},${j}`);
    }
  }
}

// Immediate emission, CRLF across chunks.
let p = createParser();
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), e => e.constructor === Error);

// Line numbers.
function lineErr(chunks, n) {
  const q = createParser();
  assert.throws(() => { for (const c of chunks) q.push(c); q.end(); },
    e => e instanceof SyntaxError && e.message.includes(`line ${n}`), JSON.stringify(chunks));
}
lineErr(['"a" ,b'], 1);
lineErr(['x\r', '\n"a\r', '\nb"x'], 3);
lineErr(['x\r\r\n\n"a"b'], 4);
lineErr(['"abc\n'], 2);
lineErr(['a\n"b\r\nc'], 3);

// Validation.
for (const d of ['"', '\r', '\n', '', ';;', 1, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);
assert.deepEqual(parse('a;"b;c"\n', { delimiter: ';' }), [['a', 'b;c']]);
assert.deepEqual(parse('a\tb', { delimiter: '\t', header: false }), [['a', 'b']]);
assert.throws(() => createParser().push(1), TypeError);
assert.deepEqual(createParser({ header: true }).push('a,b\n'), [['a', 'b']]);

// Header mode.
assert.deepEqual(parse('', { header: true }), []);
const objs = parse('x,x,x_2,x,__proto__\n1\n', { header: true });
assert.deepEqual(Object.keys(objs[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__']);
assert.equal(Object.getPrototypeOf(objs[0]), Object.prototype);
assert.equal(objs[0].x_2, '');
console.log('smoke ok');
